import{_ as l,C as d,o as s,c as o,j as a,E as e,a as n,a3 as r}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse(`{"title":"5-hafta (Mentor)","description":"","frontmatter":{"title":"5-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"n":5,"bob":"II-bob · Zamonaviy IT yo‘nalishlari va raqamli infratuzilma asoslari","lessons":[{"g":13,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (3-qism): sinxronlash, xavfsizlik va mini-loyiha","lead":"Telefonda olgan rasmingiz bir zumda kompyuterda paydo bo'ladi, do'stingiz bilan bitta taqdimotni bir vaqtda yozasiz. Bugun buning qanday ishlashini, ma'lumotlaringizni bulutda qanday himoya qilishni bilib olasiz va jamoa bo'lib birinchi «bulutdagi loyiha»ni bajarasiz.","link":"/mentor/8-sinf-cs/hafta-05/dars-1","slide":"/slaydlar/8-sinf-cs/hafta-05/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-05/dars-1-test.html"},{"g":14,"title":"Git va GitHub bilan tanishuv (1-qism): versiya nazorati, repository va commit","lead":"referat_oxirgi.docx, referat_oxirgi_ROSTDAN_v3.docx... Qaysi biri to'g'ri? Dasturchilar bu muammoni ancha oldin hal qilgan: ular har bir o'zgarishni «saqlash nuqtasi» sifatida yozib boradi. Bugun bu tizim — Git va uning bulutdagi uyi — GitHub bilan tanishasiz.","link":"/mentor/8-sinf-cs/hafta-05/dars-2","slide":"/slaydlar/8-sinf-cs/hafta-05/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-05/dars-2-test.html"},{"g":15,"title":"Git va GitHub bilan tanishuv (2-qism): kompyuterda Git — init, status, add, commit, log","lead":"O'tgan darsda commitni sayt orqali qildingiz. Haqiqiy dasturchilar esa o'z kompyuterida, terminalda ishlaydi — internetsiz ham. Bugun beshta buyruq bilan o'z «kundalik» repository'ingizni yaratasiz va uning tarixini ko'rasiz.","link":"/mentor/8-sinf-cs/hafta-05/dars-3","slide":"/slaydlar/8-sinf-cs/hafta-05/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-05/dars-3-test.html"}],"test":"/slaydlar/8-sinf-cs/hafta-05/hafta-test.html"}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-05/index.md","filePath":"mentor/8-sinf-cs/hafta-05/index.md"}`),h={name:"mentor/8-sinf-cs/hafta-05/index.md"},c={class:"blk"},g={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},u={class:"blk"},m={id:"baholash-mezoni",tabindex:"-1"};function y(b,t,x,v,k,f){const i=d("Icon");return s(),o("div",null,[a("div",c,[a("h2",g,[e(i,{name:"house"}),t[0]||(t[0]=n(" Uyga vazifa va mentor tavsiyalari ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),t[2]||(t[2]=r('<p>Har bir vazifa 20–30 daqiqa vaqt oladi. Vazifalar daftarda yoki kompyuterda alohida papkada saqlanadi. Akkaunt kerak bo&#39;lgan qadamlarni ota-onangiz ruxsati va yordami bilan bajaring; akkaunt yoki Git bo&#39;lmasa, shu qadamni daftarda chizma, jadval yoki «commit kartochkalari» ko&#39;rinishida bajaring.</p><h2 id="_13-dars-uchun-bulutli-xizmatlar-3-qism" tabindex="-1">13-dars uchun (Bulutli xizmatlar, 3-qism) <a class="header-anchor" href="#_13-dars-uchun-bulutli-xizmatlar-3-qism" aria-label="Permalink to &quot;13-dars uchun (Bulutli xizmatlar, 3-qism)&quot;">​</a></h2><p><strong>1-topshiriq: «Mening bulutim xavfsizmi?»</strong></p><ol><li>O&#39;zingizning (yoki ota-onangiz bilan tanlangan namunaviy) 3 ta bulutdagi faylingiz uchun ruxsatlar auditi jadvalini tuzing: fayl, kim kira oladi, qanday ruxsat, o&#39;zgartirish kerakmi.</li><li>Kamida bitta keraksiz ruxsatni olib tashlang yoki «Havolasi bor har kim» ni <strong>Cheklangan</strong> ga o&#39;zgartiring (yoki daftarda qanday qilishni yozing).</li><li>Bulutdagi xotirangiz qancha band ekanini toping va joyni bo&#39;shatishning 3 qadamli rejasini yozing.</li><li>Bulutda xavfsizlikning 5 qoidasidan oilangiz uchun «eslatma varaqasi» tayyorlang.</li></ol><p><strong>Kutiladigan natija:</strong> 3 qatorli audit jadvali, kamida 1 ta tuzatilgan ruxsat, xotira rejasi va 5 bandli eslatma.</p><h2 id="_14-dars-uchun-git-va-github-1-qism" tabindex="-1">14-dars uchun (Git va GitHub, 1-qism) <a class="header-anchor" href="#_14-dars-uchun-git-va-github-1-qism" aria-label="Permalink to &quot;14-dars uchun (Git va GitHub, 1-qism)&quot;">​</a></h2><p><strong>2-topshiriq: «Men haqimda» repository&#39;si</strong></p><ol><li>GitHub&#39;da <code>men-haqimda</code> nomli repository&#39;ni <strong>Add a README file</strong> bilan yarating.</li><li>README&#39;ni Markdown&#39;da to&#39;ldiring: <code>#</code> sarlavha, <code>##</code> «Qiziqishlarim» bo&#39;limi, <strong>qalin</strong> matn va kamida 3 bandli ro&#39;yxat. Telefon raqami va manzil yozmang!</li><li>Kamida <strong>3 ta commit</strong> qiling, har biriga tushunarli xabar yozing.</li><li>Commits sahifasidan har commitning xabari, vaqti va qisqa ID&#39;sini daftarga yozing.</li></ol><p><strong>Kutiladigan natija:</strong> repository havolasi, formatlangan README va 3 ta commit jadvali.</p><h2 id="_15-dars-uchun-git-va-github-2-qism" tabindex="-1">15-dars uchun (Git va GitHub, 2-qism) <a class="header-anchor" href="#_15-dars-uchun-git-va-github-2-qism" aria-label="Permalink to &quot;15-dars uchun (Git va GitHub, 2-qism)&quot;">​</a></h2><p><strong>3-topshiriq: «Kundalik» davomi</strong></p><ol><li>Darsdagi <code>kundalik</code> repository&#39;sida har kun uchun bitta fayl yarating (<code>seshanba.txt</code>, <code>chorshanba.txt</code>, ...) — kamida 3 ta yangi fayl.</li><li>Har bir faylni alohida commit qiling (<code>git add</code> → <code>git commit -m &quot;...&quot;</code>), har safar oldin va keyin <code>git status</code> ni tekshiring.</li><li><code>README.md</code> ga «Bu hafta nimani o&#39;rgandim» bo&#39;limini qo&#39;shib, commit qiling.</li><li><code>git log --oneline</code> natijasining skrinshotini oling yoki daftarga ko&#39;chiring (kamida 6 ta commit).</li></ol><p><strong>Kutiladigan natija:</strong> kamida 6 ta commitli tarix va har bir commit uchun aniq xabar.</p><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>16-dars boshida 3-topshiriqdagi <code>kundalik</code> repository&#39;lari GitHub&#39;ga <strong>push</strong> qilinadi — o&#39;quvchilar papkani o&#39;chirmasligi va kompyuterni almashtirmasligi kerak (yoki papkani fleshkaga nusxalab olsin). 2-topshiriqda README&#39;dagi shaxsiy ma&#39;lumotlarni tekshiring. Commit xabarlarini baholashda «nima o&#39;zgardi?» savoliga javob berishiga qarang; <code>asdf</code>, <code>123</code> kabi xabarlar uchun ball kamaytiriladi. Git o&#39;rnatilmagan uyda topshiriq «commit kartochkalari» (har kartada: xabar, sana, o&#39;zgargan fayl) bilan bajarilishi mumkin.</p>',15))]),a("div",u,[a("h2",m,[e(i,{name:"list-checks"}),t[3]||(t[3]=n(" Baholash mezoni ",-1)),t[4]||(t[4]=a("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),t[5]||(t[5]=r('<p>Dasturdagi mezonlarga asoslangan (100 ballik shkala): <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><p>Dasturda joriy nazorat (amaliy mashg&#39;ulotlar, darsdagi faollik, tezkor savol-javoblar, uy vazifasi, mini-loyihalar va <strong>GitHub laboratoriya ishlari</strong>) o&#39;quv jarayoni davomida o&#39;tkaziladi. Quyida 5-haftaning 3 ta darsi bo&#39;yicha har bir o&#39;quvchi ishtirokini qayd etish uchun baholash jadvali keltirilgan.</p><h2 id="mezonlar-har-bir-dars-uchun" tabindex="-1">Mezonlar (har bir dars uchun) <a class="header-anchor" href="#mezonlar-har-bir-dars-uchun" aria-label="Permalink to &quot;Mezonlar (har bir dars uchun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th style="text-align:center;">Max ball</th><th>Tavsif</th></tr></thead><tbody><tr><td>Nazariya va tushunchalar</td><td style="text-align:center;">30</td><td>Sinxronlash, xotira hajmlari, bulut xavfsizligi; VCS, Git va GitHub, repository, commit, branch, README; uch hudud va 5 ta buyruq</td></tr><tr><td>Amaliy ko&#39;nikmalar</td><td style="text-align:center;">30</td><td>Ruxsatlar auditi va mini-loyiha; GitHub&#39;da repository, README (Markdown), commit; terminalda <code>init</code>, <code>status</code>, <code>add</code>, <code>commit</code>, <code>log</code></td></tr><tr><td>Xavfsizlik va hamkorlik</td><td style="text-align:center;">20</td><td>Eng kam ruxsat, akkauntdan chiqish, README&#39;da shaxsiy ma&#39;lumot yo&#39;qligi; guruhli loyihadagi hissa; tushunarli commit xabarlari</td></tr><tr><td>Uyga vazifa</td><td style="text-align:center;">20</td><td>Uy vazifasi to&#39;liq, sifatli va vaqtida bajarilgan</td></tr><tr><td><strong>Jami</strong></td><td style="text-align:center;"><strong>100</strong></td><td></td></tr></tbody></table><hr><h2 id="_13-dars-bulutli-xizmatlar-3-qism-sinxronlash-xavfsizlik-va-mini-loyiha" tabindex="-1">13-dars (Bulutli xizmatlar, 3-qism: sinxronlash, xavfsizlik va mini-loyiha) <a class="header-anchor" href="#_13-dars-bulutli-xizmatlar-3-qism-sinxronlash-xavfsizlik-va-mini-loyiha" aria-label="Permalink to &quot;13-dars (Bulutli xizmatlar, 3-qism: sinxronlash, xavfsizlik va mini-loyiha)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Hamkorlik /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><p>Mini-loyihada «Hamkorlik» mezoni bo&#39;yicha kuzating: o&#39;quvchining hissasi versiya tarixida ko&#39;rinadimi, Trello kartasini bajardimi, jamoadoshiga izoh qoldirib, izohga javob berdimi, yakuniy auditda ochiq havola qolmaganmi.</p><hr><h2 id="_14-dars-git-va-github-1-qism-versiya-nazorati-repository-va-commit" tabindex="-1">14-dars (Git va GitHub, 1-qism: versiya nazorati, repository va commit) <a class="header-anchor" href="#_14-dars-git-va-github-1-qism-versiya-nazorati-repository-va-commit" aria-label="Permalink to &quot;14-dars (Git va GitHub, 1-qism: versiya nazorati, repository va commit)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Xavfsizlik /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_15-dars-git-va-github-2-qism-init-status-add-commit-log-—-laboratoriya-ishi" tabindex="-1">15-dars (Git va GitHub, 2-qism: init, status, add, commit, log — laboratoriya ishi) <a class="header-anchor" href="#_15-dars-git-va-github-2-qism-init-status-add-commit-log-—-laboratoriya-ishi" aria-label="Permalink to &quot;15-dars (Git va GitHub, 2-qism: init, status, add, commit, log — laboratoriya ishi)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Xavfsizlik /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><p>Laboratoriya ishida «Amaliyot» mezoni: <code>git config</code> sozlangan (5), <code>git init</code> bajarilgan va <code>.git</code> topilgan (5), birinchi commit (10), qo&#39;shimcha 2 ta commit va <code>git log --oneline</code> natijasi (10).</p><hr><h2 id="_5-hafta-yakuni" tabindex="-1">5-hafta yakuni <a class="header-anchor" href="#_5-hafta-yakuni" aria-label="Permalink to &quot;5-hafta yakuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">13-dars</th><th style="text-align:center;">14-dars</th><th style="text-align:center;">15-dars</th><th style="text-align:center;">O&#39;rtacha ball</th><th style="text-align:center;">Yakuniy baho</th><th>Izoh va tavsiyalar</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr></tbody></table><hr><h2 id="hafta-xulosasi-va-keyingi-darslarga-ko-prik" tabindex="-1">Hafta xulosasi va keyingi darslarga ko&#39;prik <a class="header-anchor" href="#hafta-xulosasi-va-keyingi-darslarga-ko-prik" aria-label="Permalink to &quot;Hafta xulosasi va keyingi darslarga ko&#39;prik&quot;">​</a></h2><p>O&#39;quvchilar bulutli xizmatlar mavzusini yakunladilar: sinxronlash va oflayn rejim, xotira hajmlari, bulutda xavfsizlik va ruxsatlar auditi; guruhda «Bulutdagi sinf loyihasi»ni bajardilar. So&#39;ng Git va GitHub bilan tanishdilar: versiya nazorati g&#39;oyasi, repository, commit, branch, README, GitHub&#39;da birinchi repository va kompyuterda lokal ish jarayoni (<code>init</code> → <code>status</code> → <code>add</code> → <code>commit</code> → <code>log</code>). 6-haftada (16–17-darslar) <code>kundalik</code> repository&#39;si GitHub&#39;ga <code>push</code> qilinadi, <code>clone</code>, <code>pull</code> va <code>branch</code> bilan jamoaviy ish o&#39;rganiladi.</p>',21))])])}const p=l(h,[["render",y]]);export{z as __pageData,p as default};
